import{_ as a,o as n,c as t,a5 as p}from"./chunks/framework.Bhkz_BpM.js";const h=JSON.parse('{"title":"MS-00 环境与最小离散控制模型","description":"","frontmatter":{"title":"MS-00 环境与最小离散控制模型","date":"2026-07-09T00:00:00.000Z","quality":"curated","status":"learning","visibility":"public","order":10,"summary":"用一个一阶对象和离散 PI 控制器建立最小仿真闭环，先跑通采样周期、状态更新、限幅和日志。"},"headers":[],"relativePath":"content/matlab-simulink/foundation/MS-00-Simulation-Setup.md","filePath":"content/matlab-simulink/foundation/MS-00-Simulation-Setup.md","lastUpdated":null}'),e={name:"content/matlab-simulink/foundation/MS-00-Simulation-Setup.md"};function l(m,s,i,c,r,o){return n(),t("div",null,[...s[0]||(s[0]=[p(`<h1 id="ms-00-环境与最小离散控制模型" tabindex="-1">MS-00 环境与最小离散控制模型 <a class="header-anchor" href="#ms-00-环境与最小离散控制模型" aria-label="Permalink to &quot;MS-00 环境与最小离散控制模型&quot;">​</a></h1><p>新手做仿真最容易卡在工具细节上。更好的开始方式是先写一个小到不能再小的闭环：一个一阶对象，一个离散 PI，一个采样周期，一组日志。</p><h2 id="_1-建模边界" tabindex="-1">1. 建模边界 <a class="header-anchor" href="#_1-建模边界" aria-label="Permalink to &quot;1. 建模边界&quot;">​</a></h2><p>最小模型只保留这些量：</p><div class="kb-table-scroll"><table><thead><tr><th>变量</th><th>含义</th><th>建议初值</th></tr></thead><tbody><tr><td><code>Ts</code></td><td>控制器采样周期</td><td><code>1e-4</code> 到 <code>1e-3</code></td></tr><tr><td><code>tau</code></td><td>一阶对象时间常数</td><td><code>0.02</code></td></tr><tr><td><code>ref</code></td><td>目标值</td><td><code>1.0</code></td></tr><tr><td><code>u</code></td><td>控制输出</td><td>限幅到 <code>[-1, 1]</code></td></tr><tr><td><code>y</code></td><td>对象输出</td><td>初值为 <code>0</code></td></tr></tbody></table></div><p>连续一阶对象可以写成：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mover accent="true"><mi>y</mi><mo>˙</mo></mover><mo>=</mo><mfrac><mrow><mo>−</mo><mi>y</mi><mo>+</mo><mi>K</mi><mi>u</mi></mrow><mi>τ</mi></mfrac></mrow><annotation encoding="application/x-tex">\\dot y = \\frac{-y + K u}{\\tau}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8623em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.0833em;"><span class="mord">˙</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0463em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">−</span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mord mathnormal">u</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span><p>用前向欧拉离散化后，每个采样周期更新一次：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>y</mi><mo stretchy="false">[</mo><mi>k</mi><mo>+</mo><mn>1</mn><mo stretchy="false">]</mo><mo>=</mo><mi>y</mi><mo stretchy="false">[</mo><mi>k</mi><mo stretchy="false">]</mo><mo>+</mo><msub><mi>T</mi><mi>s</mi></msub><mfrac><mrow><mo>−</mo><mi>y</mi><mo stretchy="false">[</mo><mi>k</mi><mo stretchy="false">]</mo><mo>+</mo><mi>K</mi><mi>u</mi><mo stretchy="false">[</mo><mi>k</mi><mo stretchy="false">]</mo></mrow><mi>τ</mi></mfrac></mrow><annotation encoding="application/x-tex">y[k+1] = y[k] + T_s \\frac{-y[k] + K u[k]}{\\tau}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mopen">[</span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">]</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mopen">[</span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mclose">]</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.113em;vertical-align:-0.686em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">−</span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mopen">[</span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mclose">]</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mord mathnormal">u</span><span class="mopen">[</span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mclose">]</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span><h2 id="_2-最小-matlab-脚本" tabindex="-1">2. 最小 Matlab 脚本 <a class="header-anchor" href="#_2-最小-matlab-脚本" aria-label="Permalink to &quot;2. 最小 Matlab 脚本&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ts = 1e-3;</span></span>
<span class="line"><span>Tend = 1.0;</span></span>
<span class="line"><span>N = round(Tend / Ts);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Kplant = 1.0;</span></span>
<span class="line"><span>tau = 0.02;</span></span>
<span class="line"><span>Kp = 0.8;</span></span>
<span class="line"><span>Ki = 30.0;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ref = ones(1, N);</span></span>
<span class="line"><span>y = zeros(1, N);</span></span>
<span class="line"><span>u = zeros(1, N);</span></span>
<span class="line"><span>integ = 0;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>for k = 1:N-1</span></span>
<span class="line"><span>    err = ref(k) - y(k);</span></span>
<span class="line"><span>    integ = integ + Ts * err;</span></span>
<span class="line"><span>    u(k) = Kp * err + Ki * integ;</span></span>
<span class="line"><span>    u(k) = min(max(u(k), -1.0), 1.0);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    y(k + 1) = y(k) + Ts * (-y(k) + Kplant * u(k)) / tau;</span></span>
<span class="line"><span>end</span></span>
<span class="line"><span></span></span>
<span class="line"><span>t = (0:N-1) * Ts;</span></span>
<span class="line"><span>plot(t, ref, &#39;--&#39;, t, y);</span></span>
<span class="line"><span>grid on;</span></span>
<span class="line"><span>legend(&#39;ref&#39;, &#39;y&#39;);</span></span>
<span class="line"><span>xlabel(&#39;time / s&#39;);</span></span></code></pre></div><p>先不要急着调复杂参数。确认曲线能跟踪、输出没有无限增大、改变 <code>Ts</code> 后结果有合理变化，这一步才算过关。</p><h2 id="_3-最小检查表" tabindex="-1">3. 最小检查表 <a class="header-anchor" href="#_3-最小检查表" aria-label="Permalink to &quot;3. 最小检查表&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>检查项</th><th>通过标准</th></tr></thead><tbody><tr><td>采样周期统一</td><td>脚本、模型、控制器都使用同一个 <code>Ts</code></td></tr><tr><td>控制输出有限</td><td><code>u</code> 有明确上下限</td></tr><tr><td>状态更新只有一次</td><td>每个循环只更新一次 <code>y[k+1]</code></td></tr><tr><td>日志长度一致</td><td><code>t</code>、<code>ref</code>、<code>y</code>、<code>u</code> 长度一致</td></tr><tr><td>参数可复现实验</td><td>改 <code>Kp</code>、<code>Ki</code> 后曲线变化能解释</td></tr></tbody></table></div><h2 id="_4-什么时候进入-simulink" tabindex="-1">4. 什么时候进入 Simulink <a class="header-anchor" href="#_4-什么时候进入-simulink" aria-label="Permalink to &quot;4. 什么时候进入 Simulink&quot;">​</a></h2><p>当你能用脚本解释每个变量的来源，再进入 Simulink 会顺很多。Simulink 的价值不是替代思考，而是把采样、模块边界、数据流和多速率关系展示出来。</p>`,16)])])}const y=a(e,[["render",l]]);export{h as __pageData,y as default};
